INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4918723, 714498, 97225, '<td valign="top">This is excellent creativity.</td>', 'This is excellent creativity.', '2008-08-28 23:00:45.000000', NULL, 1),
(4918724, 713735, 97225, '<td valign="top">I like the color balance and compositional balance and it makes me want to go along too.</td>', 'I like the color balance and compositional balance and it makes me want to go along too.', '2008-08-28 23:02:00.000000', NULL, 1),
(4918728, 714646, 97225, '<td valign="top">No wonder this is less travelled. It is beautiful in its wildness but it looks lonely and a bit dangerous.</td>', 'No wonder this is less travelled. It is beautiful in its wildness but it looks lonely and a bit dangerous.', '2008-08-28 23:03:35.000000', NULL, 1),
(4918737, 714285, 97225, '<td valign="top">This is charming. The little girl looking back gives the impression of a slight apprehension about taking this road to adventure.</td>', 'This is charming. The little girl looking back gives the impression of a slight apprehension about taking this road to adventure.', '2008-08-28 23:08:58.000000', NULL, 1),
(4918740, 713873, 97225, '<td valign="top">Good shot. This sure looks like it doesn''y get much traffic.</td>', 'Good shot. This sure looks like it doesn''y get much traffic.', '2008-08-28 23:12:08.000000', NULL, 1),
(4918742, 714488, 19641, '<td valign="top">Nice shot!  I like the contrast as well as the way you''ve framed the shot, however, I''m not sure about the tilt.  It may have been just a little much.  I also find the shiny thing down the road a little distracting.  Not sure if that''s a car or sign.  Anyway...  I like the image.</td>', 'Nice shot!  I like the contrast as well as the way you''ve framed the shot, however, I''m not sure about the tilt.  It may have been just a little much.  I also find the shiny thing down the road a little distracting.  Not sure if that''s a car or sign.  Anyway...  I like the image.', '2008-08-28 23:13:10.000000', NULL, 1),
(4918744, 714465, 97225, '<td valign="top">I''m glad they have this to themselves. Nice shot.</td>', 'I''m glad they have this to themselves. Nice shot.', '2008-08-28 23:13:27.000000', NULL, 1),
(4918747, 714418, 97225, '<td valign="top">Beautiful picture. That would be a nice road to explore.</td>', 'Beautiful picture. That would be a nice road to explore.', '2008-08-28 23:14:44.000000', NULL, 1),
(4918748, 714383, 54228, '<td valign="top">Ooooh, dreamy. I like the effect.</td>', 'Ooooh, dreamy. I like the effect.', '2008-08-28 23:14:53.000000', NULL, 1),
(4918749, 714451, 54228, '<td valign="top">Great interpretation of the challenge, the image itself is quite haunting as well. Nice use of light and tones. Me likes.</td>', 'Great interpretation of the challenge, the image itself is quite haunting as well. Nice use of light and tones. Me likes.', '2008-08-28 23:15:33.000000', NULL, 1),
(4918752, 714193, 97225, '<td valign="top">This shot has a great atmosphere. I love the soft focus and the hint of a path that should only be taken with due respect.</td>', 'This shot has a great atmosphere. I love the soft focus and the hint of a path that should only be taken with due respect.', '2008-08-28 23:16:22.000000', NULL, 1),
(4918754, 714313, 19641, '<td valign="top">Decent image.  Basic portrait with good color\skin tone and I love the spin on the "Road Less Traveled" theme.  My constructive criticism would have to be the shiny area on the side of his head and the dust on his shoulder.  Otherwise good image.</td>', 'Decent image.  Basic portrait with good color\skin tone and I love the spin on the "Road Less Traveled" theme.  My constructive criticism would have to be the shiny area on the side of his head and the dust on his shoulder.  Otherwise good image.', '2008-08-28 23:17:47.000000', NULL, 1),
(4918755, 713504, 97225, '<td valign="top">Looks pretty busy out there.Good juxtaposition of elements.</td>', 'Looks pretty busy out there.Good juxtaposition of elements.', '2008-08-28 23:18:30.000000', NULL, 1),
(4918756, 713721, 47541, '<td valign="top">The DOF is good if not a little shallow.  I''d prefer to see more blue in the background rather than more "bland" brown.  I also wonder if this wouldn''t have been a better composition if the ducks were heading from left to right instead of right to left?  If you had them, some road signs or something to link it to the challenge more would have been good.</td>', 'The DOF is good if not a little shallow.  I''d prefer to see more blue in the background rather than more "bland" brown.  I also wonder if this wouldn''t have been a better composition if the ducks were heading from left to right instead of right to left?  If you had them, some road signs or something to link it to the challenge more would have been good.', '2008-08-28 23:19:14.000000', NULL, 1),
(4918757, 714427, 97225, '<td valign="top">That is a lovely picture.</td>', 'That is a lovely picture.', '2008-08-28 23:19:24.000000', NULL, 1),
(4918758, 714195, 19641, '<td valign="top">This photo definitely caught my attention but in my humble opinion the colors are a little over saturated and I would like to see more of the road around the curve.  Perhaps a different angle of different spot on the road would have made the difference.  Overall...  Great image.</td>', 'This photo definitely caught my attention but in my humble opinion the colors are a little over saturated and I would like to see more of the road around the curve.  Perhaps a different angle of different spot on the road would have made the difference.  Overall...  Great image.', '2008-08-28 23:20:16.000000', NULL, 1),
(4918762, 714564, 97225, '<td valign="top">At least the postie must be travelling this road.</td>', 'At least the postie must be travelling this road.', '2008-08-28 23:21:31.000000', NULL, 1),
(4918764, 713239, 97225, '<td valign="top">That is a nice twist.</td>', 'That is a nice twist.', '2008-08-28 23:21:56.000000', NULL, 1),
(4918769, 713239, 19641, '<td valign="top">I like your take on the theme but for me the image could be better.  I''m not sure about the angle for even the crop.  Too bad it wasn''t advanced editing.  I think this would look cool if everything was in B&amp;W accept the flowers.  Atleast you took the time to shoot something and get it in which is more than I can say for myself.</td>', 'I like your take on the theme but for me the image could be better.  I''m not sure about the angle for even the crop.  Too bad it wasn''t advanced editing.  I think this would look cool if everything was in B&W accept the flowers.  Atleast you took the time to shoot something and get it in which is more than I can say for myself.', '2008-08-28 23:23:03.000000', NULL, 1),
(4918773, 714457, 97225, '<td valign="top">Terrific shot. And I bet the traffic is minimal.</td>', 'Terrific shot. And I bet the traffic is minimal.', '2008-08-28 23:23:46.000000', NULL, 1),
(4918779, 714564, 19641, '<td valign="top">I like the lighting, the road, the mailboxes.  In my humble opinion it could have been better without the power lines.</td>', 'I like the lighting, the road, the mailboxes.  In my humble opinion it could have been better without the power lines.', '2008-08-28 23:24:20.000000', NULL, 1),
(4918784, 714676, 19641, '<td valign="top">Great lightening shot but not really my favorite for "The Road Less Traveled".  The lightening takes too much attention away from the road.</td>', 'Great lightening shot but not really my favorite for "The Road Less Traveled".  The lightening takes too much attention away from the road.', '2008-08-28 23:25:35.000000', NULL, 1),
(4918785, 714508, 97225, '<td valign="top">I really like the effect you have got here. It enhances the feeling of loneliness and nostalgia.</td>', 'I really like the effect you have got here. It enhances the feeling of loneliness and nostalgia.', '2008-08-28 23:25:51.000000', NULL, 1),
(4918790, 712512, 19641, '<td valign="top">Nice shot!  There''s not a lot to it but I think it''s the simplicity that attracks me to it.  I feel like I''m going to get hit from behind so I really feel like I''m drawn into the shot.  Great work!</td>', 'Nice shot!  There''s not a lot to it but I think it''s the simplicity that attracks me to it.  I feel like I''m going to get hit from behind so I really feel like I''m drawn into the shot.  Great work!', '2008-08-28 23:27:14.000000', NULL, 1),
(4918793, 713647, 97225, '<td valign="top">That is an excellent take.</td>', 'That is an excellent take.', '2008-08-28 23:27:52.000000', NULL, 1),
(4918794, 714348, 97225, '<td valign="top">Interesting take on this challenge.</td>', 'Interesting take on this challenge.', '2008-08-28 23:28:30.000000', NULL, 1),
(4918795, 714383, 19641, '<td valign="top">Wow!  In my mind this shot had huge potential.  However, for me it''s just a little too contrasty and it''s way over saturated.  Great road and well composed!</td>', 'Wow!  In my mind this shot had huge potential.  However, for me it''s just a little too contrasty and it''s way over saturated.  Great road and well composed!', '2008-08-28 23:28:31.000000', NULL, 1),
(4918798, 713411, 97225, '<td valign="top">Beautiful photo.</td>', 'Beautiful photo.', '2008-08-28 23:30:06.000000', NULL, 1),
(4918799, 712518, 19641, '<td valign="top">This is a fantastic shot!  In my opinion this could have been a ribon contender, however I think the person and the van will take away from it.  Otherwise...  I really love this shot!</td>', 'This is a fantastic shot!  In my opinion this could have been a ribon contender, however I think the person and the van will take away from it.  Otherwise...  I really love this shot!', '2008-08-28 23:30:35.000000', NULL, 1),
(4918802, 713468, 97225, '<td valign="top">Good shot.The track leads in well.</td>', 'Good shot.The track leads in well.', '2008-08-28 23:32:29.000000', NULL, 1),
(4918803, 714526, 19641, '<td valign="top">Fantastic!  I sincerely try to offer constructive criticism when I do there reviews but I have nothing for this one.</td>', 'Fantastic!  I sincerely try to offer constructive criticism when I do there reviews but I have nothing for this one.', '2008-08-28 23:33:08.000000', NULL, 1),
(4918804, 714209, 97225, '<td valign="top">I keep coming back for another look at this. It draws me in.</td>', 'I keep coming back for another look at this. It draws me in.', '2008-08-28 23:34:22.000000', NULL, 1),
(4918806, 713437, 97225, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2008-08-28 23:35:32.000000', NULL, 1),
(4918807, 714661, 19641, '<td valign="top">This is a great shot but did it comply with the basic editing rules?  It looks like you converted to B&amp;W then did localized editing to bring the color back in the individual.  I could be wrong about both but this shot leaves me wondering.  Otherwise...  This is a really good photo.</td>', 'This is a great shot but did it comply with the basic editing rules?  It looks like you converted to B&W then did localized editing to bring the color back in the individual.  I could be wrong about both but this shot leaves me wondering.  Otherwise...  This is a really good photo.', '2008-08-28 23:35:46.000000', NULL, 1),
(4918812, 713612, 97225, '<td valign="top">Beautifil shot, and suitably lonely.</td>', 'Beautifil shot, and suitably lonely.', '2008-08-28 23:38:10.000000', NULL, 1),
(4918823, 713588, 97225, '<td valign="top">Lovely color but it doesn''t seem to be focused enough. I think it is stretching to connect this to the challenge.</td>', 'Lovely color but it doesn''t seem to be focused enough. I think it is stretching to connect this to the challenge.', '2008-08-28 23:42:04.000000', NULL, 1),
(4918826, 714598, 97225, '<td valign="top">I think the color and focus let this down a bit.</td>', 'I think the color and focus let this down a bit.', '2008-08-28 23:43:53.000000', NULL, 1),
(4918827, 714609, 97225, '<td valign="top">This has a nice feel to it.</td>', 'This has a nice feel to it.', '2008-08-28 23:44:45.000000', NULL, 1),
(4918830, 714108, 97225, '<td valign="top">Good comparison because less suggests there must be more as well.</td>', 'Good comparison because less suggests there must be more as well.', '2008-08-28 23:46:19.000000', NULL, 1),
(4918832, 713981, 97225, '<td valign="top">Lovely shot. It beckons me to seek what is around that bend.</td>', 'Lovely shot. It beckons me to seek what is around that bend.', '2008-08-28 23:47:59.000000', NULL, 1),
(4918836, 714550, 97225, '<td valign="top">Nice place. Pity that some litterer has come that way.</td>', 'Nice place. Pity that some litterer has come that way.', '2008-08-28 23:49:36.000000', NULL, 1),
(4918839, 714041, 97225, '<td valign="top">Great shot. It looks like there is no shortage of travellers here though.</td>', 'Great shot. It looks like there is no shortage of travellers here though.', '2008-08-28 23:52:08.000000', NULL, 1),
(4918845, 713053, 97225, '<td valign="top">You can have that road on your own. Good shot.</td>', 'You can have that road on your own. Good shot.', '2008-08-28 23:59:24.000000', NULL, 1),
(4918848, 712786, 97225, '<td valign="top">It''s a pity you cut his foot off. The central composition doesn''t work for me. Maybe you could have got him further up the track and included a bit more of a hint of the bend in the road. Also it could be a bit sharper.</td>', 'It''s a pity you cut his foot off. The central composition doesn''t work for me. Maybe you could have got him further up the track and included a bit more of a hint of the bend in the road. Also it could be a bit sharper.', '2008-08-29 00:03:49.000000', NULL, 1),
(4918849, 713774, 97225, '<td valign="top">That is lovely.</td>', 'That is lovely.', '2008-08-29 00:06:19.000000', NULL, 1),
