(4919814, 713239, 83313, '<td valign="top">I''m sure he likes assertive women. Why wait for him to come around, eh? I suspect you are getting killed with low DNMC votes, but I see how this fits the idea. Not caring for the bit of a skew on the porch. I like the somewhat retro color treatment, though.</td>', 'I''m sure he likes assertive women. Why wait for him to come around, eh? I suspect you are getting killed with low DNMC votes, but I see how this fits the idea. Not caring for the bit of a skew on the porch. I like the somewhat retro color treatment, though.', '2008-08-29 14:37:48.000000', NULL, 1),
(4919823, 713979, 83313, '<td valign="top">A very nice shot and a metaphor that I know is there, but I am not totally getting the message. Perhaps referring to someone who has either retired, or passed away?</td>', 'A very nice shot and a metaphor that I know is there, but I am not totally getting the message. Perhaps referring to someone who has either retired, or passed away?', '2008-08-29 14:42:37.000000', NULL, 1),
(4919826, 714457, 83313, '<td valign="top">Fascinating image, but I am having a hard time seeing this as an actual road, nor as a metaphor for choices in life.</td>', 'Fascinating image, but I am having a hard time seeing this as an actual road, nor as a metaphor for choices in life.', '2008-08-29 14:43:50.000000', NULL, 1),
(4919829, 714648, 83313, '<td valign="top">Pretty darn sharp for no lens! This technique also hides sensor dust well.</td>', 'Pretty darn sharp for no lens! This technique also hides sensor dust well.', '2008-08-29 14:46:46.000000', NULL, 1),
(4920249, 712786, 1024, '<td valign="top">This is one of my favorite shots in this challenge.  It meets the challenge in a less obvious way which is refreshing.  The tones and color cast are both lovely!  I bet this gentleman has interesting stories to tell.</td>', 'This is one of my favorite shots in this challenge.  It meets the challenge in a less obvious way which is refreshing.  The tones and color cast are both lovely!  I bet this gentleman has interesting stories to tell.', '2008-08-29 18:01:20.000000', NULL, 1),
(4920252, 713155, 1024, '<td valign="top">This definitely meets the challenge in an interesting way. I love old abandoned or neglected buildings, and the same goes for roads.  I think if you tweaked the contrast this image would really pop.  Nice  choice to go with black and white.  The clouds really help the composition.</td>', 'This definitely meets the challenge in an interesting way. I love old abandoned or neglected buildings, and the same goes for roads.  I think if you tweaked the contrast this image would really pop.  Nice  choice to go with black and white.  The clouds really help the composition.', '2008-08-29 18:03:28.000000', NULL, 1),
(4920259, 713981, 1024, '<td valign="top">These clouds really make the photo.  I really just want to walk down this road a ways.</td>', 'These clouds really make the photo.  I really just want to walk down this road a ways.', '2008-08-29 18:05:21.000000', NULL, 1),
(4920269, 713873, 1024, '<td valign="top">This is definatly my kind of photo op.  I love places like this.  Great job. 10</td>', 'This is definatly my kind of photo op.  I love places like this.  Great job. 10', '2008-08-29 18:12:16.000000', NULL, 1),
(4920270, 713645, 1024, '<td valign="top">Eye opening and gut wrenching all in one photo.  The background adds to the specialness of this image.  This is my choice for the blue.  Good luck (10)</td>', 'Eye opening and gut wrenching all in one photo.  The background adds to the specialness of this image.  This is my choice for the blue.  Good luck (10)', '2008-08-29 18:13:51.000000', NULL, 1),
(4920271, 713647, 1024, '<td valign="top">This is one of the most interesting images in this challenge.  There are so many questions here, and very few answers.  I just love the suspence.</td>', 'This is one of the most interesting images in this challenge.  There are so many questions here, and very few answers.  I just love the suspence.', '2008-08-29 18:14:02.000000', NULL, 1),
(4920278, 713239, 1024, '<td valign="top">This is an unusual take on the challenge, but definitely meets the challenge in my eyes.  I love the humor here.  Unfortunately I do not see this as being DPC friendly.  I give you kudos for taking the risk.  Thanks for the smile.</td>', 'This is an unusual take on the challenge, but definitely meets the challenge in my eyes.  I love the humor here.  Unfortunately I do not see this as being DPC friendly.  I give you kudos for taking the risk.  Thanks for the smile.', '2008-08-29 18:17:54.000000', NULL, 1),
(4920294, 713647, 651, '<td valign="top">Nice picture.</td>', 'Nice picture.', '2008-08-29 18:22:55.000000', NULL, 1),
(4920302, 714488, 651, '<td valign="top">I think if your picture was taken about 15 feet off the ground the road would have been unbroken.</td>', 'I think if your picture was taken about 15 feet off the ground the road would have been unbroken.', '2008-08-29 18:24:58.000000', NULL, 1),
(4920316, 714501, 651, '<td valign="top">We all go away someday, so how is this road less traveled?</td>', 'We all go away someday, so how is this road less traveled?', '2008-08-29 18:29:18.000000', NULL, 1),
(4920336, 713414, 651, '<td valign="top">I would have liked better focus across the front of the car.. Not just the headlight/bumper area..</td>', 'I would have liked better focus across the front of the car.. Not just the headlight/bumper area..', '2008-08-29 18:39:18.000000', NULL, 1),
(4920348, 714412, 19011, '<td valign="top">I absolutely dig this! One of my fav''s</td>', 'I absolutely dig this! One of my fav''s', '2008-08-29 18:46:07.000000', NULL, 1),
(4920350, 714387, 59276, '<td valign="top">I like the leading lines.....</td>', 'I like the leading lines.....', '2008-08-29 18:46:17.000000', NULL, 1),
(4920357, 713645, 651, '<td valign="top">Nice idea,</td>', 'Nice idea,', '2008-08-29 18:48:35.000000', NULL, 1),
(4920358, 714348, 651, '<td valign="top">Great idea.. I would have liked it more focused..</td>', 'Great idea.. I would have liked it more focused..', '2008-08-29 18:48:38.000000', NULL, 1),
(4920359, 714242, 651, '<td valign="top">Nice picture but, we all will travel this road... So not really "less traveled"..</td>', 'Nice picture but, we all will travel this road... So not really "less traveled"..', '2008-08-29 18:48:41.000000', NULL, 1),
(4920360, 714029, 651, '<td valign="top">My eye is drawn to the bench. I really have to look for the woman.</td>', 'My eye is drawn to the bench. I really have to look for the woman.', '2008-08-29 18:48:48.000000', NULL, 1),
(4920361, 712509, 651, '<td valign="top">Nice use of leading lines.</td>', 'Nice use of leading lines.', '2008-08-29 18:49:09.000000', NULL, 1),
(4920365, 714285, 19011, '<td valign="top">The red pole on the right is quite distracting, but I love the little girl and the teddy lookig back. Nice shot.</td>', 'The red pole on the right is quite distracting, but I love the little girl and the teddy lookig back. Nice shot.', '2008-08-29 18:49:52.000000', NULL, 1),
(4920367, 713351, 19011, '<td valign="top">Awesome shot!!! But ? meeting challenge?</td>', 'Awesome shot!!! But ? meeting challenge?', '2008-08-29 18:52:30.000000', NULL, 1),
(4920375, 713774, 19011, '<td valign="top">Can not really make up my mind on this one. Very dramatic, yet... cool actually!</td>', 'Can not really make up my mind on this one. Very dramatic, yet... cool actually!', '2008-08-29 18:57:35.000000', NULL, 1),
(4920385, 712633, 19011, '<td valign="top">2nd best shot for me!</td>', '2nd best shot for me!', '2008-08-29 19:00:50.000000', NULL, 1),
(4920400, 714530, 97796, '<td valign="top">I really like this picture... I''m not exactly sure why. I just like the way that this road looks like it never ends. And it makes me want to know just what is around that bend?</td>', 'I really like this picture... I''m not exactly sure why. I just like the way that this road looks like it never ends. And it makes me want to know just what is around that bend?', '2008-08-29 19:09:36.000000', NULL, 1),
(4920406, 714041, 97796, '<td valign="top">I don''t really like this picture, partly becouse it dosen''t really follow the theme. Anyone looking at THIS picture would think that it is "The Road Most Traveled"! And the image dosen''t really have much point to me... It dosen''t leave me longing for more, it dosen''t look that impressive or awesome, and it dosen''t look like it would be to hard to take.</td>', 'I don''t really like this picture, partly becouse it dosen''t really follow the theme. Anyone looking at THIS picture would think that it is "The Road Most Traveled"! And the image dosen''t really have much point to me... It dosen''t leave me longing for more, it dosen''t look that impressive or awesome, and it dosen''t look like it would be to hard to take.', '2008-08-29 19:13:05.000000', NULL, 1),
(4920414, 714488, 97796, '<td valign="top">WOW. When this image popped up on my screen, I was just kind of stunned. Why? Because the way the black road contrasts with the brownish-orange sand, it just looks cool. And the way the road seems to wind into nothing, with such a cool vantage point. I love it. Especially the dark mountains in the background... and for me, it is just feels good to look at.</td>', 'WOW. When this image popped up on my screen, I was just kind of stunned. Why? Because the way the black road contrasts with the brownish-orange sand, it just looks cool. And the way the road seems to wind into nothing, with such a cool vantage point. I love it. Especially the dark mountains in the background... and for me, it is just feels good to look at.', '2008-08-29 19:17:11.000000', NULL, 1),
(4920436, 713612, 96723, '<td valign="top">beautiful color quality and cantrast</td>', 'beautiful color quality and cantrast', '2008-08-29 19:50:12.000000', NULL, 1),
(4920437, 714487, 96723, '<td valign="top">didn''t like the orange lines, feel it is a distraction.</td>', 'didn''t like the orange lines, feel it is a distraction.', '2008-08-29 19:51:03.000000', NULL, 1),
(4920490, 713645, 94265, '<td valign="top">This is really great, very poignant.</td>', 'This is really great, very poignant.', '2008-08-29 20:31:09.000000', NULL, 1),
(4920531, 714451, 60658, '<td valign="top">I hope I am reading this image correctly, as I see he has chosen the wrong road!?  Nice image, would have liked to have seen the model dirtier looking if I am correct about your interpretation.</td>', 'I hope I am reading this image correctly, as I see he has chosen the wrong road!?  Nice image, would have liked to have seen the model dirtier looking if I am correct about your interpretation.', '2008-08-29 21:08:03.000000', NULL, 1),
(4920699, 714597, 90624, '<td valign="top">I was going to do one similar to this with the scriptures.. glad to see it was thought of!!</td>', 'I was going to do one similar to this with the scriptures.. glad to see it was thought of!!', '2008-08-29 23:16:22.000000', NULL, 1),
(4920725, 714391, 35334, '<td valign="top">.</td>', '.', '2008-08-29 23:43:20.000000', NULL, 1),
(4920806, 714646, 97927, '<td valign="top">wow!!!!</td>', 'wow!!!!', '2008-08-30 00:32:01.000000', NULL, 1),
(4920839, 713411, 60495, '<td valign="top">Very nice shot but a real stretch on challenge topic</td>', 'Very nice shot but a real stretch on challenge topic', '2008-08-30 01:05:42.000000', NULL, 1),
(4920845, 714389, 60495, '<td valign="top">I like the scene but to me the over processing just does not do the image justice. Some of the leaves also look like they are over exposed especially the ones towards the top of the image.</td>', 'I like the scene but to me the over processing just does not do the image justice. Some of the leaves also look like they are over exposed especially the ones towards the top of the image.', '2008-08-30 01:14:14.000000', NULL, 1),
(4920924, 714108, 48471, '<td valign="top">Good idea to confront two types of roads, but I''m not sure about the realization.</td>', 'Good idea to confront two types of roads, but I''m not sure about the realization.', '2008-08-30 03:35:19.000000', NULL, 1),
(4920925, 714125, 48471, '<td valign="top">Looks like a graphic picture from the books of travellers from two centuries ago.</td>', 'Looks like a graphic picture from the books of travellers from two centuries ago.', '2008-08-30 03:37:44.000000', NULL, 1),
(4920928, 714117, 48471, '<td valign="top">It''s interesting how the picture is divided into two parts.</td>', 'It''s interesting how the picture is divided into two parts.', '2008-08-30 03:40:25.000000', NULL, 1),
(4920931, 714648, 48471, '<td valign="top">:-)<br/>Good, good...</td>', ':-)Good, good...', '2008-08-30 03:42:12.000000', NULL, 1),
(4920933, 713799, 48471, '<td valign="top">Hmmm, masks are off, but I can''t see their faces...but at least I know that the masks are off.</td>', 'Hmmm, masks are off, but I can''t see their faces...but at least I know that the masks are off.', '2008-08-30 03:53:27.000000', NULL, 1),
(4921372, 713468, 62187, '<td valign="top">I want this photo to win the Blue: the subject matter is perfect for the challenge and the lighting is awesome. 10</td>', 'I want this photo to win the Blue: the subject matter is perfect for the challenge and the lighting is awesome. 10', '2008-08-30 12:22:45.000000', NULL, 1),
(4921390, 714682, 62187, '<td valign="top">The composition is great and the B&amp;W conversion works well. I can see this as being ''Less Traveled'' but not so much that weeds haven''t grown up in it. 9</td>', 'The composition is great and the B&W conversion works well. I can see this as being ''Less Traveled'' but not so much that weeds haven''t grown up in it. 9', '2008-08-30 12:36:12.000000', NULL, 1),
(4921392, 712509, 62187, '<td valign="top">Excellent choice for the challenge: 10 and I think it will place in the top 10.</td>', 'Excellent choice for the challenge: 10 and I think it will place in the top 10.', '2008-08-30 12:36:52.000000', NULL, 1),
(4921401, 714387, 62187, '<td valign="top">Wow, very nice photo. I''m guessing it''s somewhere in Southern California? Anyway - It looks like a very lonely place but it''s hard to see the ''road''. If your meaning the powerlines then they are not really ''Less Travelled'' and are more frequently traveled. Still, it''s a lovely photo and I think most people will not be as picky. I''m scoring it a 9 after all that and think it will finish in the top 10.</td>', 'Wow, very nice photo. I''m guessing it''s somewhere in Southern California? Anyway - It looks like a very lonely place but it''s hard to see the ''road''. If your meaning the powerlines then they are not really ''Less Travelled'' and are more frequently traveled. Still, it''s a lovely photo and I think most people will not be as picky. I''m scoring it a 9 after all that and think it will finish in the top 10.', '2008-08-30 12:39:46.000000', NULL, 1),
(4921403, 714487, 62187, '<td valign="top">It looks like a remote place but not ''Less Traveled''. To me, the photo shows great photography skill so I''m scoring it high: 8</td>', 'It looks like a remote place but not ''Less Traveled''. To me, the photo shows great photography skill so I''m scoring it high: 8', '2008-08-30 12:41:06.000000', NULL, 1),
(4921404, 714383, 62187, '<td valign="top">I kinda like it and I think it fits the challenge well: 9</td>', 'I kinda like it and I think it fits the challenge well: 9', '2008-08-30 12:41:57.000000', NULL, 1),
(4921407, 713645, 62187, '<td valign="top">Playin'' on my heartstrings but a stunning, emotive photo will get you a 10 everytime. I''m thinking your photo will place in the top 10.</td>', 'Playin'' on my heartstrings but a stunning, emotive photo will get you a 10 everytime. I''m thinking your photo will place in the top 10.', '2008-08-30 12:42:52.000000', NULL, 1),
(4921409, 714430, 62187, '<td valign="top">At first I was going to score this photo fairly low, at 6. Then, I realized I was stupid. Now, I totally see it as a 10 and am hoping Lucy finishes in the top 10.</td>', 'At first I was going to score this photo fairly low, at 6. Then, I realized I was stupid. Now, I totally see it as a 10 and am hoping Lucy finishes in the top 10.', '2008-08-30 12:44:12.000000', NULL, 1),
(4921411, 712862, 62187, '<td valign="top">My suggestion is that you ask your horse to take you to pick up the ribbon you must certainly be going to win. Perfect 10!</td>', 'My suggestion is that you ask your horse to take you to pick up the ribbon you must certainly be going to win. Perfect 10!', '2008-08-30 12:45:47.000000', NULL, 1),
(4921415, 714389, 62187, '<td valign="top">Wow, I think you are the only other person to reference the poem (except for me that I can tell [and my photo is doing very poorly even though it looks like Robert ''FROST'' and is more not taken then less traveled] but that doesn''t matter) and you''ve done an EXCELLENT job! I love it, the processing and subject are perfect. I''ll have to score it a 10 and I hope it gets a ribbon.</td>', 'Wow, I think you are the only other person to reference the poem (except for me that I can tell [and my photo is doing very poorly even though it looks like Robert ''FROST'' and is more not taken then less traveled] but that doesn''t matter) and you''ve done an EXCELLENT job! I love it, the processing and subject are perfect. I''ll have to score it a 10 and I hope it gets a ribbon.', '2008-08-30 12:51:56.000000', NULL, 1),
(4921416, 714655, 62187, '<td valign="top">Not so much a ''Road'' but I totally get the message. Nothing but excellence and how could I suggest anything ''helpful''? A perfect 10 and if your not in the top 10 then I''ll take that trip into the unknown!</td>', 'Not so much a ''Road'' but I totally get the message. Nothing but excellence and how could I suggest anything ''helpful''? A perfect 10 and if your not in the top 10 then I''ll take that trip into the unknown!', '2008-08-30 12:53:44.000000', NULL, 1),
(4921417, 714314, 62187, '<td valign="top">I love it - really. I bet most people hate it or maybe not? You can never tell here at DPC. I don''t care - I''m giving it a 10.</td>', 'I love it - really. I bet most people hate it or maybe not? You can never tell here at DPC. I don''t care - I''m giving it a 10.', '2008-08-30 12:53:49.000000', NULL, 1),
(4921418, 714646, 62187, '<td valign="top">I want to be there now (just not lost!). Excellent photo and a perfect 10 to me.</td>', 'I want to be there now (just not lost!). Excellent photo and a perfect 10 to me.', '2008-08-30 12:55:07.000000', NULL, 1),
(4921419, 713873, 62187, '<td valign="top">It''s kind of a haphazard photo: crooked, not clearly in focus and rather uninteresting, but! it''s a perfect choice for the Road Less Traveled and I think it deserves a 10. The ''bad'' things I mentioned only enhance your message. Well done imho.</td>', 'It''s kind of a haphazard photo: crooked, not clearly in focus and rather uninteresting, but! it''s a perfect choice for the Road Less Traveled and I think it deserves a 10. The ''bad'' things I mentioned only enhance your message. Well done imho.', '2008-08-30 12:55:11.000000', NULL, 1),
(4921420, 713981, 62187, '<td valign="top">Reminds me of where I used to live in Central Texas. Just slightly over-processed (to me and I''m guilty of that too) but I can certainly live with it. This is one of the better photos in the challenge I think and I''m hoping it will finish in the top ten. Your title is excellent: it seems like it should be a line from the poem but it''s not. 10</td>', 'Reminds me of where I used to live in Central Texas. Just slightly over-processed (to me and I''m guilty of that too) but I can certainly live with it. This is one of the better photos in the challenge I think and I''m hoping it will finish in the top ten. Your title is excellent: it seems like it should be a line from the poem but it''s not. 10', '2008-08-30 12:58:59.000000', NULL, 1),
(4921421, 714498, 62187, '<td valign="top">Some are serious, some are funny: your photo is seriously funny! Thanks and a perfect 10 to you. I hope it finishes in the top 10.</td>', 'Some are serious, some are funny: your photo is seriously funny! Thanks and a perfect 10 to you. I hope it finishes in the top 10.', '2008-08-30 12:59:40.000000', NULL, 1),
(4921426, 714457, 62187, '<td valign="top">Colors, focus, compostion - perfect. I''m sure it''s a ''Less Traveled'' place but not a traditional ''Road'' that I really think the challenge was about but I think you''ve conveyed the idea well: 9</td>', 'Colors, focus, compostion - perfect. I''m sure it''s a ''Less Traveled'' place but not a traditional ''Road'' that I really think the challenge was about but I think you''ve conveyed the idea well: 9', '2008-08-30 13:03:19.000000', NULL, 1),
(4921427, 714193, 62187, '<td valign="top">An excellent, very beautiful photo (I would certainly like to visit a place like that) that certainly conveys the idea of ''Less Traveled'' but is lacking a ''Road'' (or path) that I think the challenge really called for. It''s a 10 of a photo but for the challenge I''m going with a 9</td>', 'An excellent, very beautiful photo (I would certainly like to visit a place like that) that certainly conveys the idea of ''Less Traveled'' but is lacking a ''Road'' (or path) that I think the challenge really called for. It''s a 10 of a photo but for the challenge I''m going with a 9', '2008-08-30 13:05:48.000000', NULL, 1),
(4921430, 713799, 62187, '<td valign="top">I get your idea but it seems like it''s no big deal these days: to each their own. The generic faces are a nice touch. I see nothing wrong with the photography aspect but nothing is jumping out at me in the photo. I''ll go with a high 9.</td>', 'I get your idea but it seems like it''s no big deal these days: to each their own. The generic faces are a nice touch. I see nothing wrong with the photography aspect but nothing is jumping out at me in the photo. I''ll go with a high 9.', '2008-08-30 13:08:59.000000', NULL, 1),
(4921453, 713979, 62187, '<td valign="top">Nice idea without using a Road. I''m seeing some slight oversharpening along the left part of the folding chair: hard to avoid (for me anyway) using basic edit. Nice job overall to me. 8</td>', 'Nice idea without using a Road. I''m seeing some slight oversharpening along the left part of the folding chair: hard to avoid (for me anyway) using basic edit. Nice job overall to me. 8', '2008-08-30 13:23:37.000000', NULL, 1),
(4921459, 714113, 62187, '<td valign="top">I like it. Your ''Road'' looks very ''Less Traveled'' and the contrast is great. The only thing I think that might have improved the photo is including all of the Semi or wait until it was gone. I''m scoring your photo at 9.</td>', 'I like it. Your ''Road'' looks very ''Less Traveled'' and the contrast is great. The only thing I think that might have improved the photo is including all of the Semi or wait until it was gone. I''m scoring your photo at 9.', '2008-08-30 13:25:13.000000', NULL, 1),
(4921462, 714390, 62187, '<td valign="top">Looks pretty ''Less Traveled'': rocks over the crossbeams and not taken care of. Can''t add anything ''helpful'', it''s a perfect 10 to me.</td>', 'Looks pretty ''Less Traveled'': rocks over the crossbeams and not taken care of. Can''t add anything ''helpful'', it''s a perfect 10 to me.', '2008-08-30 13:26:33.000000', NULL, 1),
(4921464, 714571, 62187, '<td valign="top">Perfect for the challenge. Your composition is excellent. 10</td>', 'Perfect for the challenge. Your composition is excellent. 10', '2008-08-30 13:27:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4921479, 712518, 62187, '<td valign="top">You know, it''s a 10 of a photo and very eye appealing. Excellent photography work and execution. I just don''t feel it truly conveys the idea of ''Less Traveled''. You know what? I was going to score it 9 but I have a feeling your photo will win over the dpc''ers and why fight it? 10 and I think you''ve got the Blue.</td>', 'You know, it''s a 10 of a photo and very eye appealing. Excellent photography work and execution. I just don''t feel it truly conveys the idea of ''Less Traveled''. You know what? I was going to score it 9 but I have a feeling your photo will win over the dpc''ers and why fight it? 10 and I think you''ve got the Blue.', '2008-08-30 13:32:39.000000', NULL, 1),
(4921481, 713875, 62187, '<td valign="top">A really nice capture especially in what looks like very low if no lighting: 10.</td>', 'A really nice capture especially in what looks like very low if no lighting: 10.', '2008-08-30 13:33:36.000000', NULL, 1),
(4921486, 712786, 62187, '<td valign="top">I think if you would have off-set the man (not centered him), the overall imagery would have greatly improved and would have made me score your photo a 10 rather then what I hope is a respectable 8.</td>', 'I think if you would have off-set the man (not centered him), the overall imagery would have greatly improved and would have made me score your photo a 10 rather then what I hope is a respectable 8.', '2008-08-30 13:35:33.000000', NULL, 1),
