(4925653, 713468, 61315, '<td valign="top">Beautiful image, my #1 pick! I like that your road leads the viewer to that interesting old building.</td>', 'Beautiful image, my #1 pick! I like that your road leads the viewer to that interesting old building.', '2008-09-01 14:01:39.000000', NULL, 1),
(4925655, 713240, 61315, '<td valign="top">Lovely dirt road in to the woods. I like the comp and the colors are great too!</td>', 'Lovely dirt road in to the woods. I like the comp and the colors are great too!', '2008-09-01 14:03:02.000000', NULL, 1),
(4925666, 713873, 61315, '<td valign="top">Very interesting road and definitely looks forbidding! Makes me wonder why this is fenced so securely. Something valuable in there?</td>', 'Very interesting road and definitely looks forbidding! Makes me wonder why this is fenced so securely. Something valuable in there?', '2008-09-01 14:05:32.000000', NULL, 1),
(4925669, 712509, 61315, '<td valign="top">Nice serene, peaceful look to this and nice composition. 7</td>', 'Nice serene, peaceful look to this and nice composition. 7', '2008-09-01 14:06:33.000000', NULL, 1),
(4925694, 714586, 61315, '<td valign="top">I like the thought behind this but do wish the bright home in the background had been burned a bit so as not to be distracting, but maybe you left it as a contrast to the hiker? Anyway, nice shot and motion from the hiker. 7</td>', 'I like the thought behind this but do wish the bright home in the background had been burned a bit so as not to be distracting, but maybe you left it as a contrast to the hiker? Anyway, nice shot and motion from the hiker. 7', '2008-09-01 14:10:31.000000', NULL, 1),
(4925705, 714488, 61315, '<td valign="top">Not many people on the road any more, especially after the high gas prices! Looks like NV to me. Nice composition, tones in the hills, and contrast with the sky. 7 from me.</td>', 'Not many people on the road any more, especially after the high gas prices! Looks like NV to me. Nice composition, tones in the hills, and contrast with the sky. 7 from me.', '2008-09-01 14:12:52.000000', NULL, 1),
(4925719, 713437, 61315, '<td valign="top">More of a path than a road but I still like the peaceful look to this. The building looks old giving the image a deserted look. 7</td>', 'More of a path than a road but I still like the peaceful look to this. The building looks old giving the image a deserted look. 7', '2008-09-01 14:15:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4925731, 714380, 61315, '<td valign="top">I like how you used both a literal and figurative take on the topic by having a businessman on the path. Great idea! 8</td>', 'I like how you used both a literal and figurative take on the topic by having a businessman on the path. Great idea! 8', '2008-09-01 14:18:19.000000', NULL, 1),
(4925745, 714657, 61315, '<td valign="top">I hope your road doesn''t take you to a dead end! Nice landscape - I like the composition and the look of the fence, hills and sky. 7</td>', 'I hope your road doesn''t take you to a dead end! Nice landscape - I like the composition and the look of the fence, hills and sky. 7', '2008-09-01 14:21:02.000000', NULL, 1),
(4925760, 714498, 61315, '<td valign="top">This looks like one of Art''s - love the sense of humor - where do you get those little skeletons? The little turkey/knapsack is a great touch! 7</td>', 'This looks like one of Art''s - love the sense of humor - where do you get those little skeletons? The little turkey/knapsack is a great touch! 7', '2008-09-01 14:24:16.000000', NULL, 1),
(4925779, 714029, 61315, '<td valign="top">Lovely peaceful look to the road by the river and I like how the sun illuminates the bench. If it weren''t for your title, I would have missed the woman and her dog - LOL! 7</td>', 'Lovely peaceful look to the road by the river and I like how the sun illuminates the bench. If it weren''t for your title, I would have missed the woman and her dog - LOL! 7', '2008-09-01 14:28:29.000000', NULL, 1),
(4925789, 714468, 61315, '<td valign="top">Lovely old road and the inclusion of the stone bridge over the stream makes the image for me. 7</td>', 'Lovely old road and the inclusion of the stone bridge over the stream makes the image for me. 7', '2008-09-01 14:30:55.000000', NULL, 1),
(4925812, 714646, 61315, '<td valign="top">Love the look of the misty clouds in the gorge - gives the impression of being high up the mountain trail. I''m glad they have that railing there as that looks like a steep drop if you slipped!</td>', 'Love the look of the misty clouds in the gorge - gives the impression of being high up the mountain trail. I''m glad they have that railing there as that looks like a steep drop if you slipped!', '2008-09-01 14:34:20.000000', NULL, 1),
(4925819, 714661, 61315, '<td valign="top">I''m not a big fan of partial desats but I do like the idea and composition of this image. 7</td>', 'I''m not a big fan of partial desats but I do like the idea and composition of this image. 7', '2008-09-01 14:36:13.000000', NULL, 1),
