INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4942900, 714195, 36060, '<td valign="top">Great shot. Congrats on your high finish!</td>', 'Great shot. Congrats on your high finish!', '2008-09-08 19:38:09.000000', NULL, 0),
(4943236, 712862, 32786, '<td valign="top">I really like this picture.............lots</td>', 'I really like this picture.............lots', '2008-09-08 21:57:24.000000', NULL, 0),
(4943505, 714646, 39427, '<td valign="top">so what was this DQ''d for Steve?</td>', 'so what was this DQ''d for Steve?', '2008-09-09 00:11:14.000000', NULL, 0),
(4943755, 713647, 23478, '<td valign="top">Your creativity is amazing!</td>', 'Your creativity is amazing!', '2008-09-09 04:40:59.000000', NULL, 0),
(4944224, 714646, 39427, '<td valign="top">yeah that''s a bummer on that water droplet man,  on closer inspection it does change the photograph quite a bit when you remove it as it now looks like a cloud and part of the original photo.  But it would be legal in adv. editing, so that''s sort of unfair I think, but then again you have to draw the line somewhere.  IMO removing sensor dust is not qualitatively different from removing a water droplet or sun flare, but I suppose you have to draw the line somewhere.  Anyway, it is still a great photo and DID in fact place high with voters, I''m sure you''ll make it back to the top 5 in short order :)</td>', 'yeah that''s a bummer on that water droplet man,  on closer inspection it does change the photograph quite a bit when you remove it as it now looks like a cloud and part of the original photo.  But it would be legal in adv. editing, so that''s sort of unfair I think, but then again you have to draw the line somewhere.  IMO removing sensor dust is not qualitatively different from removing a water droplet or sun flare, but I suppose you have to draw the line somewhere.  Anyway, it is still a great photo and DID in fact place high with voters, I''m sure you''ll make it back to the top 5 in short order :)', '2008-09-09 11:27:54.000000', NULL, 0),
(4944685, 714655, 36060, '<td valign="top">Congrats on the 4th place. Excellent shot!</td>', 'Congrats on the 4th place. Excellent shot!', '2008-09-09 15:54:57.000000', NULL, 0),
