(4985014, 713873, 98961, '<td valign="top">i agree with the gate being to high in the frame, but i do like the photo.</td>', 'i agree with the gate being to high in the frame, but i do like the photo.', '2008-10-01 15:06:02.000000', NULL, 0),
(4986275, 714648, 59415, '<td valign="top">It is so funny how an artistic shot will get killed on DPC.  This is a cool idea and one that I would like to explore more in the future.</td>', 'It is so funny how an artistic shot will get killed on DPC.  This is a cool idea and one that I would like to explore more in the future.', '2008-10-02 00:57:39.000000', NULL, 0),
(4992650, 713528, 24212, '<td valign="top">Great detail, although I feel that the grass visible beneath the car detracts a little.</td>', 'Great detail, although I feel that the grass visible beneath the car detracts a little.', '2008-10-05 07:15:54.000000', NULL, 0),
(4997135, 713612, 62318, '<td valign="top">Nice shot of Mt Rainier.</td>', 'Nice shot of Mt Rainier.', '2008-10-07 17:00:26.000000', NULL, 0),
